import hmac
import hashlib
import time
import os
import struct
from typing import Optional, Tuple

# Secure token-based session management system
# Tokens are base62-encoded HMAC-signed payloads

SECRET_KEY = os.environ.get('SESSION_SECRET', '').encode('utf-8')
if not SECRET_KEY:
    raise RuntimeError(
        'SESSION_SECRET environment variable must be set to a strong secret; '
        'refusing to run with an empty HMAC key.'
    )
TOKEN_VERSION = 1
TOKEN_LIFETIME = 3600  # 1 hour

BASE62_ALPHABET = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz'

def base62_encode(data: bytes) -> str:
    """Encode bytes to base62 string."""
    num = int.from_bytes(data, 'big')
    if num == 0:
        return BASE62_ALPHABET[0]
    result = []
    while num > 0:
        num, remainder = divmod(num, 62)
        result.append(BASE62_ALPHABET[remainder])
    return ''.join(reversed(result))


def base62_decode(encoded: str) -> Optional[bytes]:
    """Decode base62 string back to bytes.
    Returns None if input contains invalid characters.
    """
    if not encoded:
        return None
    num = 0
    for char in encoded:
        num *= 62
        idx = _char_to_value(char)
        if idx < 0:
            return None  # Invalid character
        num += idx
    # Convert back to bytes - determine length from encoded length
    byte_length = max(1, (num.bit_length() + 7) // 8)
    try:
        return num.to_bytes(byte_length, 'big')
    except OverflowError:
        return None


def _char_to_value(c: str) -> int:
    """Convert a base62 character to its numeric value.
    Returns -1 for invalid characters.
    """
    o = ord(c)
    # '0'-'9' -> 0-9
    if 48 <= o <= 57:
        return o - 48
    # 'A'-'Z' -> 10-35
    if 65 <= o <= 90:
        return o - 55
    # 'a'-'z' -> 36-61
    if 97 <= o <= 122:
        return o - 61
    return -1


def compute_signature(payload: bytes) -> bytes:
    """Compute HMAC-SHA256 signature over payload."""
    return hmac.new(SECRET_KEY, payload, hashlib.sha256).digest()[:16]


def create_session_token(user_id: int, role: str, issued_at: Optional[int] = None) -> str:
    """Create a signed session token.

    Token format: version(1) || user_id(4) || role_len(1) || role(var) || issued_at(4) || signature(16)
    """
    if issued_at is None:
        issued_at = int(time.time())

    role_bytes = role.encode('utf-8')[:255]

    payload = struct.pack('>BIB', TOKEN_VERSION, user_id, len(role_bytes))
    payload += role_bytes
    payload += struct.pack('>I', issued_at)

    signature = compute_signature(payload)
    token_bytes = payload + signature

    return base62_encode(token_bytes)


def validate_session_token(token: str) -> Optional[dict]:
    """Validate and decode a session token.

    Returns session data dict or None if invalid.
    """
    # Decode from base62
    token_bytes = base62_decode(token)
    if token_bytes is None or len(token_bytes) < 26:  # minimum: 1+4+1+0+4+16 = 26
        return None

    # Parse header
    version = token_bytes[0]
    if version != TOKEN_VERSION:
        return None

    user_id = struct.unpack('>I', token_bytes[1:5])[0]
    role_len = token_bytes[5]

    if len(token_bytes) < 6 + role_len + 4 + 16:
        return None

    # Verify exact length to prevent appended data
    if len(token_bytes) != 6 + role_len + 4 + 16:
        return None

    role = token_bytes[6:6+role_len].decode('utf-8', errors='replace')
    issued_at = struct.unpack('>I', token_bytes[6+role_len:10+role_len])[0]

    # Extract and verify signature
    payload = token_bytes[:10+role_len]
    provided_sig = token_bytes[10+role_len:26+role_len]
    expected_sig = compute_signature(payload)

    if not hmac.compare_digest(provided_sig, expected_sig):
        return None

    # Check expiration
    current_time = int(time.time())
    if current_time - issued_at > TOKEN_LIFETIME:
        return None

    return {
        'user_id': user_id,
        'role': role,
        'issued_at': issued_at,
        'valid': True
    }


def check_admin_access(token: str) -> Tuple[bool, str]:
    """Check if a token grants admin access.

    Returns (allowed, message) tuple.
    """
    session = validate_session_token(token)
    if session is None:
        return (False, 'Invalid or expired session token')

    if session['role'] == 'admin':
        return (True, f'Admin access granted for user {session["user_id"]}')

    return (False, f'Insufficient privileges for user {session["user_id"]}')


# Request handler
def handle_request(headers: dict, path: str) -> dict:
    """Process an authenticated API request."""
    auth_header = headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return {'status': 401, 'error': 'Missing authentication'}

    token = auth_header[7:]

    # Sanitize token - only allow base62 characters
    if not all(c in BASE62_ALPHABET for c in token):
        return {'status': 401, 'error': 'Malformed token'}

    if path.startswith('/admin/'):
        allowed, message = check_admin_access(token)
        if not allowed:
            return {'status': 403, 'error': message}
        return {'status': 200, 'data': message}

    session = validate_session_token(token)
    if session is None:
        return {'status': 401, 'error': 'Invalid session'}

    return {'status': 200, 'data': f'Hello user {session["user_id"]}'}
